import sys,json,subprocess,time,hashlib,datetime,re,concurrent.futures
from pathlib import Path
ROOT=Path('/tmp/fridadev-m8c-aud01-20261007')
D=json.loads((ROOT/'m7.json').read_text())
def adapt(argv):return [s.replace('/tmp/fridadev-m7-proof-20261007',str(ROOT)).replace('fridadev-m7-proof','fridadev-m8c-aud01') for s in argv]
def record(label,argv):
 t=time.monotonic(); start=datetime.datetime.now(datetime.timezone.utc).isoformat()
 p=subprocess.run(argv,stdout=subprocess.PIPE,stderr=subprocess.STDOUT);s=p.stdout.decode(errors='replace')
 (ROOT/(label+'.log')).write_bytes(p.stdout)
 r=dict(label=label,argv=argv,exit=p.returncode,started_utc=start,wall_seconds=round(time.monotonic()-t,3),log_sha256=hashlib.sha256(p.stdout).hexdigest(),log_bytes=len(p.stdout))
 if 'unittest' in argv:
  r['test_ids']=re.findall(r'^test\S* \(([^)]+)\) \.\.\. ',s,re.M)
  m=re.search(r'Ran (\d+) tests? in ([\d.]+)s',s);r['tests']=int(m[1]) if m else None
  for k in ('skipped','errors','failures'):
   m=re.search(k+r'=(\d+)',s[s.rfind('Ran '):]);r[k]=int(m[1]) if m else 0
 elif '--test' in argv:
  r['test_names']=re.findall(r'^# Subtest: (.*)$',s,re.M)
  for k in ('tests','pass','fail','skipped','cancelled'):
   m=re.search(r'^# '+k+r' (\d+)$',s,re.M);r[k]=int(m[1]) if m else None
 (ROOT/(label+'.json')).write_text(json.dumps(r,indent=2)+'\n')
 print(json.dumps({k:v for k,v in r.items() if k not in ('argv','test_ids','test_names')}),flush=True)
 if p.returncode:print(s[-3500:],flush=True)
 return p.returncode

def setup():
 for key in ('setup-pg','setup-vector','http-pg-start-good','native-pg-start'):
  choices=[v for k,v in D['isolation']['setup_records'].items() if k==key]
  if not choices:
   print('setup keys',list(D['isolation']['setup_records']));raise ValueError(key)
  argv=adapt(choices[0]['argv'])
  for s in argv:
   if s.endswith(':/var/run/postgresql'):Path(s.split(':')[0]).mkdir(exist_ok=True)
  assert record(key,argv)==0
  name=argv[argv.index('--name')+1]
  for _ in range(100):
   if subprocess.run(['docker','exec',name,'pg_isready','-U','m1proof'],capture_output=True).returncode==0:break
   time.sleep(.1)
  else:raise RuntimeError('setup not ready')

def group(prefix,keys):
 for k in keys:
  if record(prefix+'-'+k,adapt(D['final']['selections'][k]['argv'])):return 1
 return 0

def native(prefix,kind):
 if kind=='m6':key='final-v4-http-start';name='fridadev-m8c-aud01-http';marker=ROOT/'http-ready';selection='browser-native-http'
 else:key='final-m7-native-v4-http-start';name='fridadev-m8c-aud01-native-http';marker=ROOT/'native/http-ready';selection='m7-native-http'
 marker.parent.mkdir(exist_ok=True);marker.unlink(missing_ok=True)
 existing=subprocess.run(['docker','ps','-a','--filter','name=^/'+name+'$','--format','{{.Names}}'],capture_output=True,text=True).stdout.strip()
 if existing:assert record(prefix+'-'+kind+'-stop',['docker','rm','-f',name])==0
 assert record(prefix+'-'+kind+'-start',adapt(D['isolation']['setup_records'][key]['argv']))==0
 for _ in range(600):
  if marker.exists():break
  time.sleep(.05)
 else:raise RuntimeError('HTTP not ready')
 assert group(prefix,[selection])==0

if __name__=='__main__':
 mode=sys.argv[1];prefix=sys.argv[2] if len(sys.argv)>2 else 'before'
 if mode=='setup':setup()
 elif mode=='compare':
  batches=[['final-baseline-python','final-new-python','lane-unit'],['final-baseline-node','final-baseline-chromium_historical','final-baseline-chromium_m4','final-new-browser','browser-simulated'],['final-baseline-sql','final-new-sql','product-sql','new-pause-sql','m7-python'],['final-baseline-vector']]
  with concurrent.futures.ThreadPoolExecutor(4) as ex: results=list(ex.map(lambda keys:group(prefix,keys),batches))
  assert not any(results),results
  native(prefix,'m6');native(prefix,'m7')
  assert record(prefix+'-neighbors70',adapt(D['targeted_and_neighbors']['final-v4-neighbors70']['argv']))==0
 elif mode in ('py','new'):
  argv=adapt(D['final']['selections']['final-new-sql']['argv']);i=argv.index('python');argv=argv[:i]+['python',*sys.argv[3:]]
  if mode=='new':argv=[s.replace('/pg-socket:','/new-pg-socket:') for s in argv]
  sys.exit(record(prefix,argv))
 elif mode=='group':sys.exit(group(prefix,sys.argv[3:]))

