import io,json,unittest,zipfile
from unittest.mock import patch
from core import document_renderer_contract as c
from core.document_rendering import RenderingSession
from tests.support import document_renderer_fixtures as f
from tests.support.document_renderer_fake import FakeRenderer
NS='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
P='<w:p><w:r><w:t>Synthetic</w:t></w:r></w:p>'
def replace_document(body,xml):
 out=io.BytesIO()
 with zipfile.ZipFile(io.BytesIO(body)) as old,zipfile.ZipFile(out,'w') as new:
  for info in old.infolist():new.writestr(info,xml.encode() if info.filename=='word/document.xml' else old.read(info))
 return out.getvalue()
class Reproduction(unittest.TestCase):
 def run_case(self,xml,refused):
  request=c.make_request(job_id=f.JOB,revision_id=f.REVISION,canonical=f.canonical(),canonical_sha256=c.digest(c.json_bytes(f.canonical())),format='docx',engine=f.ENGINE)
  m,d,p=f.result(c,request)
  if xml is not None:d=replace_document(d,xml)
  m['artifacts']['docx'].update(byte_size=len(d),sha256=c.digest(d));m['page_evidence']['docx_sha256']=c.digest(d)
  worker=FakeRenderer();events=[];original=c.validate_result
  def result(req):worker.events.append('result');return f.response(c,m,d,p)
  worker.result=result
  def validate(*args,**kw):
   events.append('validation_entered')
   try:r=original(*args,**kw)
   except c.RendererError:events.append('validation_refused');raise
   events.append('validation_accepted');return r
  session=RenderingSession(client=worker,expected_engine=f.ENGINE,wait=lambda:None)
  self.addCleanup(lambda:print(json.dumps({'case':self._testMethodName,'worker_events':worker.events,'validation_events':events,'local_collected':session.collected is not None})))
  with patch.object(c,'validate_result',validate):
   if refused:
    with self.assertRaises(c.RendererError):session.collect(request,check=lambda:None)
    self.assertEqual(worker.events[-1],'cancel');self.assertNotIn('release',worker.events);self.assertIsNone(session.collected)
   else:self.assertEqual(session.collect(request,check=lambda:None).release['state'],'released')
 def test_nominal_control(self):self.run_case(None,False)
 def test_truncated_xml_control(self):self.run_case('<w:document xmlns:w="'+NS+'"><w:body>',True)
 def test_two_bodies_expected_refusal(self):self.run_case('<w:document xmlns:w="'+NS+'"><w:body>'+P+'</w:body><w:body>'+P+'</w:body></w:document>',True)
 def test_foreign_root_child_expected_refusal(self):self.run_case('<w:document xmlns:w="'+NS+'"><foreign>Not a WordprocessingML body</foreign></w:document>',True)
unittest.main(verbosity=2)

