import concurrent.futures,json
from pathlib import Path
from proof import ROOT,D,adapt,record
jobs=[]
for name,key in [('python','final_python_record'),('frontend','final_frontend_record'),('m7_python','new_python_record'),('m7_frontend','new_frontend_record')]:
 jobs.append(('final-load-'+name,adapt(D['identifier_loading'][key]['argv'])))
for name,r in D['versions'].items():jobs.append(('observed-'+name,adapt(r['argv'])))
with concurrent.futures.ThreadPoolExecutor(4) as ex:
 results=list(ex.map(lambda pair:record(*pair),jobs))
assert not any(results)
for label,_ in jobs:
 if label.startswith('observed-'):
  r=json.loads((ROOT/(label+'.json')).read_text());r['content_free_output']=(ROOT/(label+'.log')).read_text().splitlines();(ROOT/(label+'.json')).write_text(json.dumps(r,indent=2)+'\n')
